/**
 * Delivery-mode metadata. Mirrors the C# <c>DeliveryMode</c> enum
 * on the backend. Strings match the OpenAPI <c>paths</c> schema
 * (the backend's <c>System.Text.Json</c> serializes the enum
 * numeric value by default; the alert channel-mode endpoint
 * returns the string form because of <c>JsonStringEnumConverter</c>).
 *
 * Keep the order stable — the matrix renders in this order.
 */

export const DELIVERY_MODES = ["Realtime", "Digest15m", "DigestHourly", "DigestDaily"] as const;

export type DeliveryMode = (typeof DELIVERY_MODES)[number];

export const deliveryModeLabel: Record<DeliveryMode, string> = {
  Realtime: "Realtime",
  Digest15m: "Digest (15m)",
  DigestHourly: "Digest (hourly)",
  DigestDaily: "Digest (daily)",
};

/** Short hint shown under the dropdown. */
export const deliveryModeHint: Record<DeliveryMode, string> = {
  Realtime: "Send immediately when an event matches",
  Digest15m: "Batch matches, send every 15 minutes",
  DigestHourly: "Batch matches, send every hour",
  DigestDaily: "Batch matches, send once a day",
};

/**
 * Alert-type metadata. The single source of truth for the alert
 * type labels, icons, and filter-schema references used by the
 * editor UI. Keeps the editor's "what alert is this?" branching
 * data-driven.
 */

export const ALERT_TYPES = ["News", "Market", "Disaster"] as const;

export type AlertType = (typeof ALERT_TYPES)[number];

export const alertTypeLabel: Record<AlertType, string> = {
  News: "News",
  Market: "Market",
  Disaster: "Disaster",
};

export const alertTypeOrder: ReadonlyArray<AlertType> = ["News", "Market", "Disaster"];

/** Empty filter document per type. Editor starts from this. */
export const emptyFiltersFor = (type: AlertType): string => {
  switch (type) {
    case "News":
      return JSON.stringify({ sourceIds: [], keyword: null, matchMode: "All", tags: [] });
    case "Market":
      return JSON.stringify({ symbols: [], percentThreshold: 5, windowMinutes: 60 });
    case "Disaster":
      return JSON.stringify({ regions: [], eventTypes: [], minSeverity: 5 });
  }
};

/**
 * Zod schemas for the <c>Alert.Filters</c> JSON column. Mirrors the
 * backend's typed DTOs in
 * <c>backend/src/SonrisaNews.Domain/Alerts/NewsAlertFilters.cs</c>
 * (and the Market/Disaster siblings). The backend's
 * <c>AlertFiltersSerializer</c> is the schema-validity tripwire: it
 * rejects unknown properties and per-type structural errors. The
 * Zod schemas here replicate the same shape so the editor surfaces
 * the same errors client-side before the user clicks "Save".
 *
 * The editor always round-trips through a JSON string (the
 * backend stores filters as <c>TEXT</c> on SQLite / <c>jsonb</c> on
 * Postgres). The schema parses the parsed value, then the form
 * re-serializes to canonical JSON via <c>canonicalize</c>.
 */

import { z } from "zod";

import { ALERT_TYPES, type AlertType } from "./alertTypes";

const guidSchema = z.string().uuid();

/** News filter: optional source ids, optional keyword, optional tag list. */
export const newsFiltersSchema = z
  .object({
    sourceIds: z.array(guidSchema).default([]),
    keyword: z.string().nullable().default(null),
    matchMode: z.enum(["All", "Any"]).default("All"),
    tags: z.array(z.string().min(1).max(50)).default([]),
  })
  .strict();

/** Market filter: non-empty symbol list, positive threshold, positive window. */
export const marketFiltersSchema = z
  .object({
    symbols: z.array(z.string().min(1).max(10)).min(1, "Add at least one symbol"),
    percentThreshold: z
      .number()
      .positive("Threshold must be positive")
      .max(100, "Threshold must be 100% or less"),
    windowMinutes: z
      .number()
      .int("Window must be a whole number of minutes")
      .positive("Window must be positive")
      .max(24 * 60, "Window must be 24 hours or less"),
  })
  .strict();

/** Disaster filter: regions, event types, severity threshold. */
export const disasterFiltersSchema = z
  .object({
    regions: z
      .array(z.string().min(2).max(10))
      .min(1, "Add at least one region (or use the 'global' sentinel)"),
    eventTypes: z
      .array(z.enum(["earthquake", "hurricane", "flood"]))
      .min(1, "Add at least one event type"),
    minSeverity: z.number().min(0, "Severity must be 0 or higher"),
  })
  .strict();

export type NewsFilters = z.infer<typeof newsFiltersSchema>;
export type MarketFilters = z.infer<typeof marketFiltersSchema>;
export type DisasterFilters = z.infer<typeof disasterFiltersSchema>;

export type FiltersByType = {
  News: NewsFilters;
  Market: MarketFilters;
  Disaster: DisasterFilters;
};

export const filterSchemaFor = (type: AlertType) => {
  switch (type) {
    case "News":
      return newsFiltersSchema;
    case "Market":
      return marketFiltersSchema;
    case "Disaster":
      return disasterFiltersSchema;
  }
};

export const filterSchemaByType: Record<AlertType, z.ZodTypeAny> = {
  News: newsFiltersSchema,
  Market: marketFiltersSchema,
  Disaster: disasterFiltersSchema,
};

/**
 * Parse the raw <c>Filters</c> JSON string for the given alert
 * type. Returns a field-level error on failure so the form can
 * display it next to the type picker.
 */
export const parseFilters = (type: AlertType, raw: string):
  | { success: true; data: FiltersByType[AlertType] }
  | { success: false; message: string } => {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return {
      success: false,
      message: err instanceof Error ? err.message : "Filters is not valid JSON",
    };
  }
  const schema = filterSchemaFor(type);
  const result = schema.safeParse(parsed);
  if (!result.success) {
    const first = result.error.issues[0];
    return {
      success: false,
      message: first ? `${first.path.join(".") || "filters"}: ${first.message}` : "Invalid filters",
    };
  }
  return { success: true, data: result.data as FiltersByType[AlertType] };
};

/**
 * Re-serialize parsed filters to the canonical JSON shape. Keeps
 * property order + null vs absent semantics consistent with the
 * backend's serializer output.
 */
export const canonicalize = (type: AlertType, value: FiltersByType[AlertType]): string => {
  const schema = filterSchemaFor(type);
  return JSON.stringify(schema.parse(value));
};

/** Hint that the type's filter shape is required to be non-empty. */
export const isTypeFilterEmpty = (type: AlertType, value: FiltersByType[AlertType]): boolean => {
  switch (type) {
    case "News":
      return false;
    case "Market":
      return (value as MarketFilters).symbols.length === 0;
    case "Disaster":
      return (
        (value as DisasterFilters).regions.length === 0 ||
        (value as DisasterFilters).eventTypes.length === 0
      );
  }
};

/** Compile-time guard: every AlertType has a schema. */
const _exhaustive: Record<AlertType, unknown> = {
  News: newsFiltersSchema,
  Market: marketFiltersSchema,
  Disaster: disasterFiltersSchema,
};
void _exhaustive;
void ALERT_TYPES;

import { describe, expect, it } from "vitest";

import {
  canonicalize,
  disasterFiltersSchema,
  filterSchemaFor,
  isTypeFilterEmpty,
  marketFiltersSchema,
  newsFiltersSchema,
  parseFilters,
} from "./filterSchemas";

describe("newsFiltersSchema", () => {
  it("accepts an empty filter document", () => {
    const result = newsFiltersSchema.safeParse({
      sourceIds: [],
      keyword: null,
      matchMode: "All",
      tags: [],
    });
    expect(result.success).toBe(true);
  });

  it("accepts a populated filter document", () => {
    const result = newsFiltersSchema.safeParse({
      sourceIds: ["00000000-0000-0000-0000-000000000001"],
      keyword: "earthquake",
      matchMode: "Any",
      tags: ["breaking"],
    });
    expect(result.success).toBe(true);
  });

  it("rejects an unknown property", () => {
    const result = newsFiltersSchema.safeParse({
      sourceIds: [],
      keyword: null,
      matchMode: "All",
      tags: [],
      surprise: true,
    });
    expect(result.success).toBe(false);
  });

  it("rejects a non-uuid sourceId", () => {
    const result = newsFiltersSchema.safeParse({
      sourceIds: ["not-a-uuid"],
      keyword: null,
      matchMode: "All",
      tags: [],
    });
    expect(result.success).toBe(false);
  });
});

describe("marketFiltersSchema", () => {
  it("accepts a valid market filter", () => {
    const result = marketFiltersSchema.safeParse({
      symbols: ["AAPL", "MSFT"],
      percentThreshold: 5,
      windowMinutes: 60,
    });
    expect(result.success).toBe(true);
  });

  it("rejects an empty symbol list", () => {
    const result = marketFiltersSchema.safeParse({
      symbols: [],
      percentThreshold: 5,
      windowMinutes: 60,
    });
    expect(result.success).toBe(false);
  });

  it("rejects a non-positive threshold", () => {
    const result = marketFiltersSchema.safeParse({
      symbols: ["AAPL"],
      percentThreshold: 0,
      windowMinutes: 60,
    });
    expect(result.success).toBe(false);
  });

  it("rejects a fractional window", () => {
    const result = marketFiltersSchema.safeParse({
      symbols: ["AAPL"],
      percentThreshold: 5,
      windowMinutes: 60.5,
    });
    expect(result.success).toBe(false);
  });

  it("rejects a window longer than 24 hours", () => {
    const result = marketFiltersSchema.safeParse({
      symbols: ["AAPL"],
      percentThreshold: 5,
      windowMinutes: 24 * 60 + 1,
    });
    expect(result.success).toBe(false);
  });
});

describe("disasterFiltersSchema", () => {
  it("accepts a valid disaster filter", () => {
    const result = disasterFiltersSchema.safeParse({
      regions: ["JP", "US-CA"],
      eventTypes: ["earthquake"],
      minSeverity: 5,
    });
    expect(result.success).toBe(true);
  });

  it("rejects an empty regions list", () => {
    const result = disasterFiltersSchema.safeParse({
      regions: [],
      eventTypes: ["earthquake"],
      minSeverity: 5,
    });
    expect(result.success).toBe(false);
  });

  it("rejects an unknown event type", () => {
    const result = disasterFiltersSchema.safeParse({
      regions: ["JP"],
      eventTypes: ["meteor"],
      minSeverity: 5,
    });
    expect(result.success).toBe(false);
  });

  it("rejects a negative severity", () => {
    const result = disasterFiltersSchema.safeParse({
      regions: ["JP"],
      eventTypes: ["earthquake"],
      minSeverity: -1,
    });
    expect(result.success).toBe(false);
  });
});

describe("filterSchemaFor", () => {
  it("returns the News schema for News", () => {
    expect(filterSchemaFor("News")).toBe(newsFiltersSchema);
  });

  it("returns the Market schema for Market", () => {
    expect(filterSchemaFor("Market")).toBe(marketFiltersSchema);
  });

  it("returns the Disaster schema for Disaster", () => {
    expect(filterSchemaFor("Disaster")).toBe(disasterFiltersSchema);
  });
});

describe("parseFilters", () => {
  it("parses a valid News filter string", () => {
    const raw = JSON.stringify({ sourceIds: [], keyword: null, matchMode: "All", tags: [] });
    const result = parseFilters("News", raw);
    expect(result.success).toBe(true);
  });

  it("returns a friendly error for invalid JSON", () => {
    const result = parseFilters("News", "{ not json");
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.message.length).toBeGreaterThan(0);
    }
  });

  it("returns a friendly error for a structural error", () => {
    const raw = JSON.stringify({ symbols: [], percentThreshold: 5, windowMinutes: 60 });
    const result = parseFilters("Market", raw);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.message.toLowerCase()).toContain("symbol");
    }
  });
});

describe("canonicalize", () => {
  it("round-trips a valid News filter to canonical JSON", () => {
    const raw = JSON.stringify({ sourceIds: [], keyword: null, matchMode: "All", tags: [] });
    const result = parseFilters("News", raw);
    if (!result.success) throw new Error("setup");
    const canonical = canonicalize("News", result.data);
    // The canonical form must re-parse cleanly.
    const reparsed = parseFilters("News", canonical);
    expect(reparsed.success).toBe(true);
  });
});

describe("isTypeFilterEmpty", () => {
  it("returns false for News (any shape is valid)", () => {
    const result = parseFilters(
      "News",
      JSON.stringify({ sourceIds: [], keyword: null, matchMode: "All", tags: [] }),
    );
    if (!result.success) throw new Error("setup");
    expect(isTypeFilterEmpty("News", result.data)).toBe(false);
  });

  it("returns true for Market with no symbols", () => {
    const raw = JSON.stringify({ symbols: ["AAPL"], percentThreshold: 5, windowMinutes: 60 });
    const result = parseFilters("Market", raw);
    if (!result.success) throw new Error("setup");
    // Construct a "no symbols" variant
    const empty = { ...(result.data as { symbols: string[] }), symbols: [] };
    expect(isTypeFilterEmpty("Market", empty as never)).toBe(true);
  });

  it("returns true for Disaster with no regions", () => {
    const raw = JSON.stringify({ regions: ["JP"], eventTypes: ["earthquake"], minSeverity: 5 });
    const result = parseFilters("Disaster", raw);
    if (!result.success) throw new Error("setup");
    const empty = { ...(result.data as { regions: string[] }), regions: [] };
    expect(isTypeFilterEmpty("Disaster", empty as never)).toBe(true);
  });
});

