export type ChannelResponse = {
  Id: string;
  Type: string;
  Destination: string;
  Verified: boolean;
  CreatedAt: string;
};

/** Response shape for `POST /api/v1/channels/{id}/verify/start`. */
export type VerifyStartResponse = {
  Code: string;
};

/** Body for `POST /api/v1/channels/{id}/verify/confirm`. */
export type VerifyConfirmRequest = {
  Code: string;
};

// --- Alert DTOs ---------------------------------------------------------

/** Body for `POST /api/v1/alerts`. */
export type CreateAlertRequest = {
  Name: string;
  Type: AlertTypeString;
  /** JSON string. The shape depends on <c>Type</c>; see <c>features/alerts/filterSchemas</c>. */
  Filters?: string | null;
};

/** Body for `PUT /api/v1/alerts/{id}`. */
export type UpdateAlertRequest = {
  Name?: string | null;
  Filters?: string | null;
  Enabled?: boolean | null;
};

/** Body for `POST /api/v1/alerts/{id}/channels`. */
export type SetChannelModeRequest = {
  ChannelId: string;
  Mode: DeliveryModeString;
};

/** Response shape for an alert. */
export type AlertResponse = {
  Id: string;
  Name: string;
  Type: AlertTypeString;
  Enabled: boolean;
  /** JSON string. Parse with the per-type Zod schema before reading. */
  Filters: string;
  CreatedAt: string;
  UpdatedAt: string;
};

/** Response shape for an alert-channel-mode row. */
export type AlertChannelModeResponse = {
  AlertId: string;
  ChannelId: string;
  Mode: DeliveryModeString;
  CreatedAt: string;
};

/**
 * Response shape for `POST /api/v1/alerts/{id}/test`. Each match
 * is the would-have-fired event shape: title, source, occurred
 * time, and a snippet of body. The matcher (wave 6) populates
 * this; until then the backend returns 501.
 */
export type AlertTestResponse = {
  AlertId: string;
  MatchedCount: number;
  Matches: AlertTestMatch[];
};

export type AlertTestMatch = {
  EventId: string;
  Title: string;
  Source: string;
  OccurredAt: string;
  Snippet: string;
};

/** String form of the <c>AlertType</c> C# enum (System.Text.Json + JsonStringEnumConverter). */
export type AlertTypeString = "News" | "Market" | "Disaster";

/** String form of the <c>DeliveryMode</c> C# enum. */
export type DeliveryModeString = "Realtime" | "Digest15m" | "DigestHourly" | "DigestDaily"

/**
 * Typed wrappers around the OpenAPI client for the alert + channel
 * endpoints used by the wave-5 dashboard. The wrappers exist so
 * the React Query hooks and the editor can share the same call
 * sites; the type-narrowing (e.g. <c>paths["..."]</c> indexing) is
 * in one place.
 *
 * Errors: every wrapper returns a discriminated union so the
 * caller doesn't have to know about openapi-fetch's <c>{ data,
 * error, response }</c> triple. The four useful states are:
 *   - <c>{ kind: "ok", data }</c>
 *   - <c>{ kind: "http", status, message }</c> — any non-2xx
 *   - <c>{ kind: "validation", fields }</c> — 400 with a
 *     <c>ValidationProblemDetails</c> body (the alert endpoints
 *     use this for filter errors)
 *   - <c>{ kind: "network", error }</c> — fetch threw (the
 *     401-refresh middleware has already tried to recover)
 */

import { apiClient } from "@/lib/api/client";
import type {
  AlertChannelModeResponse,
  AlertResponse,
  AlertTestResponse,
  ChannelResponse,
  CreateAlertRequest,
  SetChannelModeRequest,
  UpdateAlertRequest,
} from "@/lib/api/schema";

export type ApiResult<T> =
  | { kind: "ok"; data: T }
  | { kind: "http"; status: number; message: string }
  | { kind: "validation"; fields: Record<string, string[]> }
  | { kind: "network"; error: unknown };

const unwrap = async <T>(
  promise: ReturnType<ReturnType<typeof apiClient.POST>["response"] extends infer R
    ? (R extends Promise<infer _> ? never : never)
    : never> | Promise<{ data: T | undefined; response: Response; error: unknown }>,
): Promise<ApiResult<T>> => {
  try {
    const { data, response, error } = await promise;
    if (response.ok) {
      return { kind: "ok", data: data as T };
    }
    if (response.status === 400) {
      // Try to parse a ValidationProblemDetails body. The alert
      // controller returns one for filter validation errors.
      try {
        const body = (await response.clone().json()) as {
          errors?: Record<string, string[]>;
        };
        if (body.errors !== undefined) {
          return { kind: "validation", fields: body.errors };
        }
      } catch {
        // Body was not JSON; fall through to the generic http error.
      }
    }
    return {
      kind: "http",
      status: response.status,
      message: typeof error === "object" && error !== null && "message" in error
        ? String((error as { message: unknown }).message)
        : `HTTP ${response.status}`,
    };
  } catch (err) {
    return { kind: "network", error: err };
  }
};

// --- Alerts --------------------------------------------------------------

export const listAlerts = (): Promise<ApiResult<AlertResponse[]>> =>
  unwrap<AlertResponse[]>(apiClient.GET("/api/v1/alerts"));

export const getAlert = (id: string): Promise<ApiResult<AlertResponse>> =>
  unwrap<AlertResponse>(apiClient.GET("/api/v1/alerts/{id}", { params: { path: { id } } }));

export const createAlert = (body: CreateAlertRequest): Promise<ApiResult<AlertResponse>> =>
  unwrap<AlertResponse>(apiClient.POST("/api/v1/alerts", { body }));

export const updateAlert = (
  id: string,
  body: UpdateAlertRequest,
): Promise<ApiResult<AlertResponse>> =>
