"use client";

/**
 * Channel-mode matrix. Rows are alerts, columns are channels,
 * cells are the delivery mode dropdown. Rendering: a CSS grid
 * with a header row of channel destinations; each data row is an
 * alert (name + type) followed by one dropdown per channel.
 *
 * The matrix is a controlled component over the
 * <c>AlertChannelModeResponse</c> rows for the current alert. The
 * parent supplies:
 *   - <c>channels</c>: the caller's channel list (for the column
 *     headers)
 *   - <c>modes</c>: the current channel-mode rows for this alert
 *   - <c>onChange</c>: called with a (channelId, mode | null) pair
 *     whenever the user picks a different mode or clears a cell.
 *
 * The <c>Set</c> (or <c>Remove</c>) is delegated to the parent so
 * the matrix doesn't own the React Query mutation. This keeps the
 * matrix testable as a pure renderer + onChange callback.
 */

import Box from "@mui/material/Box";
import FormControl from "@mui/material/FormControl";
import MenuItem from "@mui/material/MenuItem";
import Select from "@mui/material/Select";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";

import {
  DELIVERY_MODES,
  deliveryModeHint,
  deliveryModeLabel,
  type DeliveryMode,
} from "./deliveryModes";
import type {
  AlertChannelModeResponse,
  AlertResponse,
  ChannelResponse,
} from "@/lib/api/schema";

export type ChannelModeMatrixProps = {
  alert: AlertResponse;
  channels: ReadonlyArray<ChannelResponse>;
  modes: ReadonlyArray<AlertChannelModeResponse>;
  onChange: (channelId: string, mode: DeliveryMode | null) => void;
  isUpdating: boolean;
};

const cellId = (alertId: string, channelId: string) => `mode-${alertId}-${channelId}`;

export function ChannelModeMatrix({
  alert,
  channels,
  modes,
  onChange,
  isUpdating,
}: ChannelModeMatrixProps) {
  const modeForChannel = (channelId: string): DeliveryMode | "" => {
    const row = modes.find((m) => m.ChannelId === channelId);
    return row?.Mode ?? "";
  };

  return (
    <Box
      role="group"
      aria-label={`Delivery modes for ${alert.Name}`}
      sx={{
        display: "grid",
        gridTemplateColumns: `minmax(160px, 1fr) repeat(${channels.length}, minmax(140px, 1fr))`,
        gap: 1,
        alignItems: "center",
      }}
    >
      <Typography variant="subtitle2" sx={{ pl: 1 }}>
        Channel
      </Typography>
      {channels.map((channel) => (
        <ChannelHeader key={channel.Id} channel={channel} />
      ))}

      <Typography variant="body2" sx={{ pl: 1 }}>
        {alert.Name}
      </Typography>
      {channels.map((channel) => {
        const value = modeForChannel(channel.Id);
        const id = cellId(alert.Id, channel.Id);
        return (
          <FormControl key={channel.Id} size="small" fullWidth>
            <Select
              id={id}
              value={value}
              displayEmpty
              disabled={isUpdating}
              onChange={(e) => {
                const next = e.target.value;
                if (next === "") {
                  onChange(channel.Id, null);
                } else {
                  onChange(channel.Id, next as DeliveryMode);
                }
              }}
              renderValue={(selected) => {
                if (selected === "" || selected === undefined) {
                  return (
                    <Typography variant="body2" color="text.secondary">
                      —
                    </Typography>
                  );
                }
                return deliveryModeLabel[selected as DeliveryMode];
              }}
              inputProps={{ "aria-label": `Delivery mode for ${alert.Name} on ${channel.Destination}` }}
            >
              <MenuItem value="">
                <em>Don&apos;t deliver</em>
              </MenuItem>
              {DELIVERY_MODES.map((mode) => (
                <MenuItem key={mode} value={mode}>
                  <Stack>
                    <Typography variant="body2">{deliveryModeLabel[mode]}</Typography>
                    <Typography variant="caption" color="text.secondary">
                      {deliveryModeHint[mode]}
                    </Typography>
                  </Stack>
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        );
      })}
    </Box>
  );
}

function ChannelHeader({ channel }: { channel: ChannelResponse }) {
  return (
    <Box sx={{ px: 1 }}>
      <Typography variant="caption" color="text.secondary">
        {channel.Type}
      </Typography>
      <Typography variant="body2" noWrap title={channel.Destination}>
        {channel.Destination}
      </Typography>
      {!channel.Verified ? (
        <Typography variant="caption" color="warning.main">
          Unverified
        </Typography>
      ) : null}
    </Box>
  );
}

"use client";

/**
 * Alert list. Server data from <c>useAlertsQuery</c>, grouped by
 * type. Each row is an <c>AlertCard</c> with the edit, delete, and
 * "test this alert" actions. Loading / error / empty states are
 * explicit. No spinners.
 *
 * The list owns the dialog open-state for the editor and the test
 * button; the cards receive callbacks. This is the only place that
 * knows about both the editor and the test dialog simultaneously.
 */

import { useMemo, useState } from "react";
import Alert from "@mui/material/Alert";
import AlertTitle from "@mui/material/AlertTitle";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Card from "@mui/material/Card";
import CardActions from "@mui/material/CardActions";
import CardContent from "@mui/material/CardContent";
import Chip from "@mui/material/Chip";
import Container from "@mui/material/Container";
import Skeleton from "@mui/material/Skeleton";
import Stack from "@mui/material/Stack";
import Switch from "@mui/material/Switch";
import Typography from "@mui/material/Typography";

import { AlertEditorDialog } from "./AlertEditorDialog";
import { TestAlertButton } from "./TestAlertButton";
import { alertTypeLabel, alertTypeOrder, type AlertType } from "./alertTypes";
import {
  useAlertsQuery,
  useDeleteAlertMutation,
  useUpdateAlertMutation,
} from "./useAlertsQueries";
import type { AlertResponse } from "@/lib/api/schema";

const SKELETON_ROWS = 3;

export function AlertList() {
  const { data, isPending, isError, error, refetch } = useAlertsQuery();
  const [editorOpen, setEditorOpen] = useState(false);
  const [editing, setEditing] = useState<AlertResponse | undefined>(undefined);

  const groups = useMemo(() => groupByType(data ?? []), [data]);

  if (isPending) {
    return (
      <Stack spacing={2} aria-busy="true">
        {Array.from({ length: SKELETON_ROWS }).map((_, i) => (
          <Skeleton key={i} variant="rectangular" height={120} />
        ))}
      </Stack>
    );
  }

  if (isError) {
    return (
      <Alert
        severity="error"
        action={
          <Button color="inherit" size="small" onClick={() => void refetch()}>
            Retry
          </Button>
        }
      >
        <AlertTitle>Couldn&apos;t load your alerts</AlertTitle>
        {error.message}
      </Alert>
    );
  }

  if (data === undefined || data.length === 0) {
    return (
      <>
        <EmptyState onCreate={() => setEditorOpen(true)} />
        <AlertEditorDialog
          open={editorOpen}
          onClose={() => setEditorOpen(false)}
          onSaved={() => setEditorOpen(false)}
        />
      </>
    );
  }

  return (
    <>
      <Stack spacing={4}>
        {alertTypeOrder.map((type) => {
          const rows = groups.get(type);
          if (rows === undefined || rows.length === 0) return null;
          return (
            <Stack key={type} spacing={1.5}>
              <Typography variant="h6" component="h2">
                {alertTypeLabel[type]}
              </Typography>
              <Stack spacing={1.5}>
                {rows.map((alert) => (
                  <AlertCard
                    key={alert.Id}
                    alert={alert}
                    onEdit={() => {
                      setEditing(alert);
                      setEditorOpen(true);
                    }}
                  />
                ))}
              </Stack>
            </Stack>
          );
        })}
      </Stack>
      <AlertEditorDialog
        open={editorOpen}
        onClose={() => {
          setEditorOpen(false);
          setEditing(undefined);
        }}
        onSaved={() => {
          setEditorOpen(false);
          setEditing(undefined);
        }}
        alert={editing}
      />
    </>
  );
}

function groupByType(alerts: ReadonlyArray<AlertResponse>): Map<AlertType, AlertResponse[]> {
  const map = new Map<AlertType, AlertResponse[]>();
  for (const type of alertTypeOrder) {
    map.set(type, []);
  }
  for (const alert of alerts) {
    const list = map.get(alert.Type);
    if (list !== undefined) list.push(alert);
  }
  return map;
}

function EmptyState({ onCreate }: { onCreate: () => void }) {
  return (
    <Card variant="outlined">
      <CardContent>
        <Stack spacing={2} alignItems="flex-start">
          <Typography variant="h6" component="h2">
            No alerts yet
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Create your first alert. Alerts are inert until the matcher wires them up
            in wave 6, so you can experiment freely.
          </Typography>
          <Button variant="contained" onClick={onCreate}>
            New alert
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
}

type AlertCardProps = {
  alert: AlertResponse;
  onEdit: () => void;
};

function AlertCard({ alert, onEdit }: AlertCardProps) {
  const deleteMutation = useDeleteAlertMutation();
  const updateMutation = useUpdateAlertMutation(alert.Id);

  const handleDelete = () => {
    if (typeof window !== "undefined") {
      const ok = window.confirm(`Delete alert "${alert.Name}"? This can't be undone.`);
      if (!ok) return;
    }
    deleteMutation.mutate(alert.Id);
  };

  const handleToggleEnabled = (_: unknown, checked: boolean) => {
    updateMutation.mutate({ Enabled: checked });
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction={{ xs: "column", sm: "row" }} spacing={1.5} alignItems="flex-start">
          <Stack spacing={0.5} sx={{ flexGrow: 1 }}>
            <Stack direction="row" spacing={1} alignItems="center">
              <Typography variant="subtitle1">{alert.Name}</Typography>
              <Chip size="small" label={alertTypeLabel[alert.Type]} />
            </Stack>
            <FilterSummary alert={alert} />
          </Stack>
          <Stack direction="row" spacing={1} alignItems="center">
            <Typography variant="caption" color="text.secondary">
              {alert.Enabled ? "Enabled" : "Disabled"}
            </Typography>
            <Switch
              checked={alert.Enabled}
              onChange={handleToggleEnabled}
              disabled={updateMutation.isPending}
              inputProps={{ "aria-label": `Enable ${alert.Name}` }}
            />
          </Stack>
        </Stack>
      </CardContent>
      <CardActions sx={{ px: 2, pb: 2, pt: 0 }}>
        <Button size="small" onClick={onEdit}>
          Edit
        </Button>
        <TestAlertButton alertId={alert.Id} alertName={alert.Name} />
        <Box sx={{ flexGrow: 1 }} />
        <Button
          size="small"
          color="error"
          onClick={handleDelete}
          disabled={deleteMutation.isPending}
        >
          Delete
        </Button>
      </CardActions>
    </Card>
  );
}

function FilterSummary({ alert }: { alert: AlertResponse }) {
  // The backend stores the per-type filter shape as a JSON
  // string. Render a one-liner summary so the card stays scannable.
  let summary = "No filter set";
  try {
    const parsed = JSON.parse(alert.Filters) as Record<string, unknown>;
    switch (alert.Type) {
      case "News": {
        const keyword = typeof parsed["keyword"] === "string" ? parsed["keyword"] : null;
        const tags = Array.isArray(parsed["tags"]) ? (parsed["tags"] as string[]) : [];
        const parts: string[] = [];
        if (keyword) parts.push(`keyword: "${keyword}"`);
        if (tags.length > 0) parts.push(`tags: ${tags.join(", ")}`);
        summary = parts.length === 0 ? "All news" : parts.join(" · ");
        break;
      }
      case "Market": {
        const symbols = Array.isArray(parsed["symbols"]) ? (parsed["symbols"] as string[]) : [];
        const threshold = parsed["percentThreshold"];
        const window = parsed["windowMinutes"];
        summary = `${symbols.join(", ") || "—"} · ±${String(threshold)}% in ${String(window)}m`;
        break;
      }
      case "Disaster": {
        const regions = Array.isArray(parsed["regions"]) ? (parsed["regions"] as string[]) : [];
        const eventTypes = Array.isArray(parsed["eventTypes"])
          ? (parsed["eventTypes"] as string[])
          : [];
        const minSeverity = parsed["minSeverity"];
        summary = `${eventTypes.join(", ") || "—"} in ${regions.join(", ") || "—"} ≥ ${String(minSeverity)}`;
        break;
      }
    }
  } catch {
    // Filters JSON is malformed; leave the default summary.
  }
  return (
    <Typography variant="body2" color="text.secondary">
      {summary}
    </Typography>
  );
}

"use client";

/**
 * "Test this alert" button. Client-side leaf that owns the test
 * dialog open-state. The matcher lands in wave 6; the button is
 * wired now so the test can be re-run as soon as wave 6 lands.
 */

import { useState } from "react";
import Button from "@mui/material/Button";

import { TestAlertDialog } from "./TestAlertDialog";

export type TestAlertButtonProps = {
  alertId: string;
  alertName: string;
};

export function TestAlertButton({ alertId, alertName }: TestAlertButtonProps) {
  const [open, setOpen] = useState(false);

  return (
    <>
      <Button size="small" onClick={() => setOpen(true)} aria-label={`Test ${alertName}`}>
        Test
      </Button>
      <TestAlertDialog
        open={open}
        onClose={() => setOpen(false)}
        alertId={alertId}
        alertName={alertName}
      />
    </>
  );
}

"use client";

/**
 * "Test this alert" dialog. Re-runs the matcher against the most
 * recent 50 events for the alert and shows the would-have-fired
 * list. The matcher lands in wave 6; until then the backend
 * returns 501 and the dialog shows a "wired in wave 6" message
 * (the test mutation throws <c>MatcherNotWiredError</c> which we
 * catch here).
 */

import { useEffect, useState } from "react";
import {
  Alert,
  AlertTitle,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from "@mui/material";

import { MatcherNotWiredError, useTestAlertMutation } from "./useAlertsQueries";
import type { AlertTestResponse } from "@/lib/api/schema";

export type TestAlertDialogProps = {
  open: boolean;
  onClose: () => void;
  alertId: string;
  alertName: string;
};

export function TestAlertDialog({
  open,
  onClose,
  alertId,
  alertName,
}: TestAlertDialogProps) {
  const mutation = useTestAlertMutation(alertId);
  const [result, setResult] = useState<AlertTestResponse | null>(null);
  const [wiringPending, setWiringPending] = useState(false);

  // Run the test as soon as the dialog opens.
  useEffect(() => {
    if (!open) return;
    setResult(null);
    setWiringPending(false);
    mutation.mutate(undefined, {
      onSuccess: (data) => setResult(data),
      onError: (err) => {
        if (err instanceof MatcherNotWiredError) {
          setWiringPending(true);
        }
      },
    });
    // We deliberately depend on `open` only — running the test
    // once per open is the right cadence. Re-running mid-dialog
    // would re-trigger a request on every state update.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Test &quot;{alertName}&quot;</DialogTitle>
      <DialogContent>
        {wiringPending ? (
          <Alert severity="info">
            <AlertTitle>Matcher not yet wired</AlertTitle>
            The matcher lands in wave 6. Once it ships, this button re-runs the
            matcher against the most recent 50 events and shows you which
            events <em>would have</em> fired this alert.
          </Alert>
        ) : mutation.isPending ? (
          <Stack alignItems="center" sx={{ py: 4 }} aria-busy="true">
            <CircularProgress />
            <Typography variant="body2" sx={{ mt: 2 }}>
              Running the matcher against the last 50 events…
            </Typography>
          </Stack>
        ) : mutation.isError && !wiringPending ? (
          <Alert severity="error">
            <AlertTitle>Test failed</AlertTitle>
            {mutation.error?.message ?? "Unknown error"}
          </Alert>
        ) : result !== null ? (
          <Stack spacing={2}>
            <Typography variant="body2" color="text.secondary">
              {result.MatchedCount === 0
                ? "No events in the last 50 would have fired this alert."
                : `${result.MatchedCount} event${result.MatchedCount === 1 ? "" : "s"} would have fired this alert.`}
            </Typography>
            {result.Matches.length > 0 ? (
              <List dense>
                {result.Matches.map((m) => (
                  <ListItem key={m.EventId} alignItems="flex-start">
                    <ListItemText
                      primary={m.Title}
                      secondary={
                        <Box component="span">
                          <Typography component="span" variant="caption" color="text.secondary">
                            {m.Source} · {new Date(m.OccurredAt).toLocaleString()}
                          </Typography>
                          <Typography component="p" variant="body2" sx={{ mt: 0.5 }}>
                            {m.Snippet}
                          </Typography>
                        </Box>
                      }
                    />
                  </ListItem>
                ))}
              </List>
            ) : null}
          </Stack>
        ) : null}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  );
}

"use client";

/**
 * Single-alert detail view. Server-fetched via the React Query
 * hooks; renders the channel-mode matrix and the alert metadata.
 * The matrix is the only editable surface on this page; the
 * alert's name / filters are edited via the editor dialog (wave 9
 * dashboard) or the channel editor (parent).
 *
 * The view is intentionally minimal: the wave 5 dashboard at
 * <c>/alerts</c> groups alerts by type and provides the editor
 * affordance from the list row. The detail page is for the
 * matrix and the "test" action.
 */

import Alert from "@mui/material/Alert";
import AlertTitle from "@mui/material/AlertTitle";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import CircularProgress from "@mui/material/CircularProgress";
import Container from "@mui/material/Container";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";

import { ChannelModeMatrix } from "./ChannelModeMatrix";
import { TestAlertButton } from "./TestAlertButton";
import { alertTypeLabel } from "./alertTypes";
import { deliveryModeLabel, type DeliveryMode } from "./deliveryModes";
import {
  useAlertChannelModesQuery,
  useChannelsQuery,
  useRemoveChannelModeMutation,
  useSetChannelModeMutation,
} from "./useAlertsQueries";
import type { AlertResponse, ChannelResponse } from "@/lib/api/schema";

export type AlertDetailProps = {
  alert: AlertResponse;
};

export function AlertDetail({ alert }: AlertDetailProps) {
  const channelsQuery = useChannelsQuery();
  const modesQuery = useAlertChannelModesQuery(alert.Id);
  const setMode = useSetChannelModeMutation(alert.Id);
  const removeMode = useRemoveChannelModeMutation(alert.Id);

  if (channelsQuery.isPending || modesQuery.isPending) {
    return (
      <Stack alignItems="center" sx={{ py: 6 }} aria-busy="true">
        <CircularProgress />
      </Stack>
    );
  }

  if (channelsQuery.isError) {
    return (
      <Alert severity="error" action={<Button onClick={() => channelsQuery.refetch()}>Retry</Button>}>
        <AlertTitle>Couldn&apos;t load your channels</AlertTitle>
        {channelsQuery.error.message}
      </Alert>
    );
  }

  const channels: ChannelResponse[] = channelsQuery.data ?? [];
  const modes = modesQuery.data ?? [];
  const isUpdating = setMode.isPending || removeMode.isPending;

  return (
    <Container maxWidth="lg" component="section" aria-label={`Alert ${alert.Name}`}>
      <Stack spacing={3} sx={{ py: 4 }}>
        <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap">
          <Typography variant="h5" component="h2">
            {alert.Name}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {alertTypeLabel[alert.Type]} · {alert.Enabled ? "Enabled" : "Disabled"}
          </Typography>
          <Box sx={{ flexGrow: 1 }} />
          <TestAlertButton alertId={alert.Id} alertName={alert.Name} />
        </Stack>

        {channels.length === 0 ? (
          <Alert severity="info">
            <AlertTitle>No channels yet</AlertTitle>
            Add a notification channel (email or Slack) to set delivery modes for this
            alert. Channels are created from the dashboard.
          </Alert>
        ) : (
          <Card variant="outlined">
            <CardContent>
              <Stack spacing={1.5}>
                <Typography variant="subtitle1">Channel × delivery mode</Typography>
                <Typography variant="body2" color="text.secondary">
                  Pick a delivery mode per channel. The matcher routes matches per
                  this matrix.
                </Typography>
                <ChannelModeMatrix
                  alert={alert}
                  channels={channels}
                  modes={modes}
                  isUpdating={isUpdating}
                  onChange={(channelId, mode) => {
                    if (mode === null) {
                      removeMode.mutate(channelId);
                    } else {
                      setMode.mutate({ ChannelId: channelId, Mode: mode });
                    }
                  }}
                />
                {modes.length > 0 ? (
                  <Typography variant="caption" color="text.secondary">
