{"content":"import { notFound } from "next/navigation";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Container from "@mui/material/Container";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Link from "next/link";

import { AlertDetail } from "@/features/alerts/AlertDetail";
import { apiClient } from "@/lib/api/client";

/**
 * Per-alert detail page. Server-rendered fetch of the alert via
 * the OpenAPI client; the page passes the result to the
 * <c>AlertDetail</c> client component which renders the
 * channel-mode matrix.
 *
 * 404 is returned for missing alerts OR alerts the caller
 * doesn't own — the controller's <c>AlertOutcome.NotFound</c>
 * maps to a 404, and the server component turns that into a
 * <c>notFound()</c>. This avoids leaking the existence of an
 * alert the caller doesn't own.
 */

async function fetchAlert(id: string) {
  const { response, data } = await apiClient.GET("/api/v1/alerts/{id}", {
    params: { path: { id } },
  });
  if (response.status === 404) {
    notFound();
  }
  if (!response.ok || data === undefined) {
    throw new Error(`Failed to fetch alert (${response.status})`);
  }
  return data;
}

export default async function AlertDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const alert = await fetchAlert(id);

  return (
    <Container maxWidth="lg" component="main">
      <Stack spacing={2} sx={{ py: 4 }}>
        <Box>
          <Button component={Link} href="/alerts" variant="text">
            ← All alerts
          </Button>
        </Box>
        <Typography variant="body2" color="text.secondary">
          Channel-mode matrix · {alert.Name}
        </Typography>
        <AlertDetail alert={alert} />
      </Stack>
    </Container>
  );
}
