{"content":""use client";

/**
 * Add-channel button that invalidates the <c>["channels"]</c>
 * query after a successful create. The plain
 * <c>AddChannelButton</c> leaf closes the dialog on success but
 * doesn't refresh the channel list — fine when the only
 * consumer of the channels list is the list page, but on the
 * alert detail page the matrix needs the new channel to appear
 * in its column headers.
 *
 * Wrap the button in this component when the matrix is on the
 * same page; the regular <c>AddChannelButton</c> is fine for the
 * dashboard / list pages.
 */

import { useQueryClient } from "@tanstack/react-query";

import { AddChannelButton } from "@/features/channels/AddChannelButton";
import { channelsQueryKey } from "@/features/alerts/useAlertsQueries";

export function AddChannelButtonWithRefresh({ label }: { label?: string }) {
  const qc = useQueryClient();
  return (
    <AddChannelButton
      label={label}
      onChannelCreated={(channelId) => {
        // Invalidate the channel list so the matrix re-renders
        // with the new column. Also invalidate the channels
        // list on the alerts page (same query key).
        void qc.invalidateQueries({ queryKey: channelsQueryKey });
        // Touch the id to keep the parameter live for future
        // hooks that may want to optimistically prepend the
        // new channel into the query cache.
        void channelId;
      }}
    />
  );
}
